questionvariables.text:
correct_answer:rand_selection([
[1, true, "The probability of literacy from any given age to any other given age."],
[2, true, "The probability of illness for any given number of persons at any age."],
[3, true, "The probability of transmitting a disease from any given age to any other given age.
"]],1);

incorrect_answers:rand_selection([
[4, false, "The probability of dying within one year of any person at each age.
"],
[5, false, "The average number of years of life remaining for a person of any age."],
[6, false, "The average number of years a newborn infant can expect to live.
"],
[7, false, "The number of persons at a particular age above or below a particular age or between any two ages under conditions of a stationary population.
"]], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
